function render(){if(!analysisBase||!channelBase||!catalog||!all)return;const routeChanged=render.lastRoute!==location.hash;render.lastRoute=location.hash;page=location.hash.slice(1).split('?')[0]||'dashboard';if(!pageInfo[page])page='dashboard';const info=pageInfo[page];$('#pageTitle').textContent=info[0];$('#pageDesc').textContent=info[1];$('#crumb').textContent=info[0];$$('nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===page));document.body.classList.remove('menu-open');$('#content').innerHTML=({costs:()=>costView.render(),weekly:()=>weeklyView.render(),dashboard:()=>salesView.render(),products:()=>location.hash.includes("report=legacy")?products():importView.render(),operations:operations,library:library,data:dataPage}[page])();bind();if(routeChanged)window.scrollTo(0,0)}
function periodRows(s=start,e=end){return all.filter(r=>r.date>=s&&r.date<=e)}
function comparison(cur,old,complete){if(!complete)return '<span>비교 기간 데이터 부족</span>';if(!old)return '<span>비교 기준 없음</span>';const p=(cur/old-1)*100;return `<span class="pill ${p<0?'negative':'positive'}">${p<0?'↘':'↗'} ${Math.abs(p).toFixed(1)}%</span><span>직전 동일 일수 대비</span>`}
function lineChart(rows,chartMode=mode){if(!rows.length)return '<div class="empty">선택 기간에 입력된 매출이 없습니다.</div>';const w=750,h=235,left=49,right=16,top=26,bottom=31,max=Math.max(...rows.map(x=>x.sales),1)*1.15;const x=i=>left+(rows.length===1?(w-left-right)/2:i/(rows.length-1)*(w-left-right)),y=n=>h-bottom-n/max*(h-top-bottom);let d=rows.map((r,i)=>(i?'L':'M')+x(i)+','+y(r.sales)).join(' ');let area=d+` L${x(rows.length-1)},${h-bottom} L${x(0)},${h-bottom} Z`;const labels=[...new Set([0,Math.floor(rows.length/4),Math.floor(rows.length/2),Math.floor(rows.length*3/4),rows.length-1])];return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="선택 기간 매출 추이"><defs><linearGradient id="areaFill" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#10AFC6" stop-opacity=".16"/><stop offset="1" stop-color="#10AFC6" stop-opacity=".01"/></linearGradient></defs>${[0,1,2,3].map(i=>{const n=max*i/3;return `<line x1="${left}" y1="${y(n)}" x2="${w-right}" y2="${y(n)}"/><text x="0" y="${y(n)+4}">${man(n)}</text>`}).join('')}<path d="${area}" fill="url(#areaFill)"/><path d="${d}" fill="none" stroke="#10AFC6" stroke-width="2.5" stroke-linejoin="round"/>${rows.map((r,i)=>`<circle cx="${x(i)}" cy="${y(r.sales)}" r="3" fill="white" stroke="#10afc6" stroke-width="1.5"><title>${r.date}${chartMode==='week'?' 주':chartMode==='month'?' 월':''} · ${won(r.sales)} · ${r.count??1}일 입력</title></circle>`).join('')}${labels.map(i=>`<text x="${x(i)}" y="${h-7}" text-anchor="middle">${rows[i].date.slice(5).replace('-','.')}</text>`).join('')}</svg>`}
function products(){const list=productKind==='bakery'?window.BAKERY:window.GELATO;const d=list.find(x=>x.id===productMonth),p=list[list.indexOf(d)-1];const delivery=d.delivery?.sales;return `<a class="btn" href="#products" style="margin-bottom:18px">← 전체 상품·옵션 분석</a><div class="note">기존 내부 리포트에서 추출한 2026년 7~9월 자료입니다. 일별 매출표의 월 합계와 리포트에 기재된 전체 매출이 서로 달라 전체 매출 대비 구성비는 계산하지 않습니다. 아래 KPI·추이·순위는 모두 <b>매장 판매 기준</b>입니다. 배달·타 매장 귀속은 포함하지 않으며 일별 총매출표와 집계 범위가 다를 수 있습니다.</div><div class="product-select"><div class="segmented"><button data-kind="bakery" class="${productKind==='bakery'?'selected':''}">베이커리</button><button data-kind="gelato" class="${productKind==='gelato'?'selected':''}">젤라또</button></div><select id="productMonth" aria-label="상품 분석 월">${list.map(x=>`<option value="${x.id}" ${x.id===productMonth?'selected':''}>${x.yearMonth}</option>`).join('')}</select></div><div class="kpis">${[['매장 판매 매출',won(d.sales),p?comparison(d.sales,p.sales,true):'첫 제공 월'],['상품 판매량',nf(d.qty)+'<small>개</small>', '세트 1개 기준 · 거래건수와 다름'],['상품당 평균 매출',won(d.sales/d.qty),'상품 매출 ÷ 판매량'],['배달 판매 매출',delivery===undefined?'자료 없음':won(delivery),'위 매장 매출과 별도 · 일별 분석 제외']].map(([t,v,f])=>`<div class="card kpi"><div class="kpi-top">${t}<span class="kpi-icon">▦</span></div><div class="kpi-value">${v}</div><div class="kpi-foot">${f}</div></div>`).join('')}</div><section class="card"><div class="card-head"><div><h3>${d.yearMonth} ${productKind==='bakery'?'베이커리':'젤라또'} 매장 판매 추이</h3><div class="sub">매장 판매만 집계 · 배달 제외</div></div><div class="legend"><i></i>매장 상품 매출</div></div>${lineChart(d.days.map((v,i)=>({date:`2026-${d.id==='jul'?'07':d.id==='aug'?'08':'09'}-${String(i+1).padStart(2,'0')}`,sales:v})),'day')}</section><div class="grid-two" style="margin-top:20px"><section class="card"><h3>분석 시 확인할 점</h3>${d.insights.map(t=>`<div class="insight-item"><p>${esc(t)}</p></div>`).join('')}<a class="btn small" style="margin-top:15px" target="_blank" rel="noopener" href="${resources[productKind==='bakery'?2:3][3]}">기존 리포트 원본 ↗</a></section><section class="card"><div class="card-head"><div><h3>매장 상품 매출 순위</h3><div class="sub">원본에 제공된 상품 목록 · ${productKind==='bakery'?'7·8월은 상위 상품만 제공':'카테고리 기준'}</div></div></div><div class="table-wrap"><table><thead><tr><th>순위</th><th>상품</th><th class="num">판매량</th><th class="num">매출</th></tr></thead><tbody>${[...d.products].sort((a,b)=>b[2]-a[2]).map((x,i)=>`<tr><td class="rank">${String(i+1).padStart(2,'0')}</td><td>${esc(x[0])}</td><td class="num">${nf(x[1])}</td><td class="num"><strong>${won(x[2])}</strong></td></tr>`).join('')}</tbody></table></div></section></div>`}
function operations(){const key=cadence==='daily'?today:cadence==='weekly'?add(today,-((date(today).getUTCDay()+6)%7)):today.slice(0,7),id=cadence+':'+key,checks=read('checks',{}),done=checks[id]||[];return `<div class="hero"><div><div class="hero-tag">STORE PROJECT MANAGEMENT</div><h2>매출을 읽고, 실행을 연결하는 PM.</h2><p>점장·현장·본사와 목표를 맞추고, 이슈의 담당자와 기한을 정하고, 결과를 확인하세요.</p></div><a class="btn cyan" href="pm-guide.md" download>↓ PM 가이드 다운로드</a></div><div class="filters ops-tabs"><div class="segmented">${[['daily','일일 업무'],['weekly','주간 업무'],['monthly','월간 업무']].map(([v,t])=>`<button data-cadence="${v}" class="${cadence===v?'selected':''}">${t}</button>`).join('')}</div><span class="sub">기준 ${key} · 기간마다 체크리스트가 새로 시작됩니다.</span></div><div class="grid-two"><section class="card"><div class="card-head"><h3>운영 체크리스트</h3><span class="badge">${done.length} / ${tasks[cadence].length} 완료</span></div><div class="progress"><i style="width:${done.length/tasks[cadence].length*100}%"></i></div>${tasks[cadence].map(([t,s],i)=>`<div class="checkrow ${done.includes(i)?'done':''}"><input type="checkbox" id="task${i}" data-check="${i}" data-key="${id}" ${done.includes(i)?'checked':''}><label for="task${i}">${t}<small>${s}</small></label></div>`).join('')}<div class="quality">체크 상태는 현재 브라우저에만 저장됩니다. 팀 공유·승인 기록은 별도 업무 도구에서 관리하세요.</div></section><section class="card"><h3>PM의 책임과 협업 범위</h3><div class="insight-item"><b>PM · 목표와 실행 관리</b><p>매출·손익 현황 파악, 우선순위 설정, 개선 실험과 일정 관리, 주간·월간 보고.</p></div><div class="insight-item"><b>점장·매장 · 현장 실행</b><p>인력 배치, 발주·재고, 품질·서비스, 마감과 일일 특이사항 기록. 실제 역할은 인수인계 시 합의하세요.</p></div><div class="insight-item"><b>본사·지원 부서 · 승인과 전문 업무</b><p>가격·예산·인사·회계·브랜드 정책의 승인 범위와 담당자를 먼저 확인하세요.</p></div><label style="margin-top:18px">나의 인수인계 메모<textarea id="pmMemo" placeholder="보고 대상, 승인 범위, 점장과의 역할 분담…">${esc(read('memo',''))}</textarea></label><button class="btn small" id="saveMemo">메모 저장</button></section></div><h2 class="section-title">첫 30일, 이렇게 시작하세요</h2><div class="roadmap"><article class="card"><div class="step">01 · 1주차</div><h3>현황과 기준 파악</h3><p>매장 방문·점장 인터뷰<br>매출·손익·인력·재고 자료 인수<br>보고·의사결정 권한 합의<br>매출 집계 기준 통일</p></article><article class="card"><div class="step">02 · 2주차</div><h3>문제와 기회 정의</h3><p>요일·시간대·상품별 패턴 확인<br>품절·폐기·대기 원인 수집<br>개선할 문제 3개 선정<br>측정 가능한 목표 합의</p></article><article class="card"><div class="step">03 · 3–4주차</div><h3>작게 실행하고 검증</h3><p>인력·발주·세트 제안 등 실험<br>담당자·기한·판단 지표 기록<br>전후 동일 조건으로 비교<br>월말 리뷰와 다음 달 계획</p></article></div>`}
function library(){return `<div class="note">Drive에서 확인한 기존 내부 자료를 모았습니다. 링크는 각 원본의 접근 권한을 따릅니다. 아래 ‘인수인계 필요 자료’는 아직 확인되지 않은 항목입니다.</div><div class="resource-grid">${resources.map(([tag,t,s,url])=>`<article class="card resource"><div class="file-icon">▤</div><span class="sub">${tag} · Google Drive</span><h3>${t}</h3><p>${s}</p><a target="_blank" rel="noopener" href="${url}">원본 자료 열기 ↗</a></article>`).join('')}</div><h2 class="section-title">인수인계 시 추가로 받아야 할 자료</h2><section class="card"><div class="table-wrap"><table><thead><tr><th>자료</th><th>확인할 내용</th><th>협의할 담당</th><th>상태</th></tr></thead><tbody>${[['운영 조직·연락망','점장·본사·공급사 연락처, 승인·보고 체계','기존 PM·본사'],['메뉴·레시피·원가표','판매가, 레시피, 수율, 채널별 수수료·할인 부담','점장·상품·회계'],['재고·발주·폐기표','기초·기말 재고, 리드타임, 안전재고, 폐기 사유','점장·구매'],['근무·인건비 현황','영업시간, 시간대별 인력, 근무 계획과 인건비','점장·인사'],['운영 매뉴얼·설비','오픈·마감, 위생, 서비스, 점검·수리 이력','점장·운영'],['계약·예산·목표','임대·거래처·플랫폼 계약, 예산, 목표 및 승인권한','본사·회계'],['고객·프로모션 이력','리뷰, 클레임, 행사 일정과 이전 실행 결과','매장·마케팅']].map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}<td><span class="badge">인수인계 필요</span></td></tr>`).join('')}</tbody></table></div></section><h2 class="section-title">바로 사용할 업무 자료</h2><div class="data-actions"><a class="btn" href="pm-guide.md" download>↓ PM 업무·인수인계 가이드</a><a class="btn" href="weekly-report.md" download>↓ 주간 보고 템플릿</a><a class="btn" href="https://www.ikovoxcoffee.com/" target="_blank" rel="noopener">브랜드 공식 홈페이지 ↗</a></div>`}
function dataPage(){const goals=read('goals',{});return `<div class="note">초기 매출은 ${base.updated}에 조회한 Drive 자료의 스냅샷입니다. <b>자동 동기화·POS 연동은 아직 연결되지 않았습니다.</b> 추가·수정·목표·체크리스트는 현재 기기와 브라우저에 저장되며 다른 기기로 공유되지 않습니다.</div><div class="grid-two"><section class="card"><h3>매출 데이터 추가</h3><p class="explain">직접 일별로 입력하거나 UTF-8 CSV를 업로드하세요. 기존 날짜는 교체 여부를 확인합니다. Excel은 ‘CSV UTF-8’로 저장해 업로드하세요.</p><div class="data-actions"><button class="btn primary" id="dataEntry">＋ 일별 입력</button><button class="btn" id="importButton">↑ CSV 업로드</button><button class="btn" id="templateButton">↓ CSV 양식</button><input hidden type="file" id="csvFile" accept=".csv,text/csv"></div><div class="quality">총매출액은 페이히어 + 오터 + 네이버 주문을 중복 없이 합친 금액으로 입력합니다. POS 상품 파일의 합계로 대체하지 마세요.<br>필수 열: 날짜, 총매출액<br>선택 열: 거래건수, 날씨, 프로모션, 특이사항, 매장<br>날짜: YYYY-MM-DD · 금액: 0 이상의 정수 · 거래건수: 0 이상의 정수 또는 공란 · 날짜당 1행 · 매장이 있으면 ‘이코복스’ 행만 반영</div><div id="importStatus" class="explain" role="status"></div></section><section class="card"><h3>월 매출 목표</h3><p class="explain">합의된 목표를 입력하면 해당 월 대시보드 배너에 달성률을 표시합니다. 목표가 없는 월에는 달성률을 표시하지 않습니다.</p><form id="goalForm"><div class="goal-form"><input name="month" aria-label="목표 월" type="month" required value="${end.slice(0,7)}"><input name="goal" aria-label="매출 목표 금액" type="number" min="1" step="1" placeholder="월 목표 금액 (원)" required value="${goals[end.slice(0,7)]||''}"><button class="btn primary small">저장</button></div></form><div class="quality">${Object.entries(goals).map(([m,g])=>`${esc(m)} · ${won(g)}`).join('<br>')||'아직 설정된 목표가 없습니다.'}</div></section></div><section class="card"><h3>데이터 보관과 내보내기</h3><p class="explain">브라우저 데이터 삭제 전 백업을 다운로드하세요. 전체 백업에는 매출 수정분, 상품·시간대 업로드, 메뉴 설정, 재료 단가·레시피, 목표, 업무 체크리스트, 메모가 포함됩니다.</p><div class="data-actions"><button class="btn" id="exportAll">↓ 전체 매출 CSV</button><button class="btn" id="backupButton">↓ 전체 백업 JSON</button><button class="btn" id="restoreButton">↑ 백업 복원</button><input hidden type="file" id="backupFile" accept=".json,application/json"><button class="btn danger" id="resetButton">로컬 변경 초기화</button></div><div class="metric-def"><h3>분석 기준</h3><p>매장 총매출 기준: POS 매장 + 배달 + 네이버 주문의 취소·환불 반영액을 중복 없이 합산합니다. 2026년 7~8월은 POS 배달앱·오터를 제외하고 배민·쿠팡이츠 커피·젤라또 원본으로 대체했습니다. 수수료 차감 후 입금액과 구분하며, 동일 주문이 두 시스템에 잡히면 한 번만 계산합니다. 기존 총매출표는 이 기준으로 원본 대조 중입니다.</p><p>거래건수는 방문 고객 수와 다릅니다. 객단가 = 선택 기간 총매출액 ÷ 거래건수 합계. 거래건수가 누락되면 객단가와 관련 증감률을 표시하지 않습니다.</p><p>주별: 월요일~일요일. 월별: 달력 월. 선택 기간과 겹치는 날짜만 집계합니다. 미입력일은 0원으로 보지 않습니다. 비교 기간은 선택 기간 직전의 동일 일수이며 양쪽 데이터가 모두 있어야 증감률을 표시합니다.</p><p>영업일은 원본 날짜를 그대로 사용하며 자정 이후 거래의 영업일 보정은 하지 않습니다. 상품 분석에는 POS·오터·네이버 확보 원본을 채널별로 연결합니다. 상품 미확인 주문과 중복 대조 상태를 함께 표시하며, 원본 수집분 합계를 확정 매장 총매출로 대체하지 않습니다.</p></div></section>`}
function download(name,text,mime='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type:mime}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
const csvCell=v=>{let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'};
function exportCSV(rows,name){download(name,'\uFEFF'+[['날짜','총매출액','거래건수','날씨','프로모션','특이사항'],...rows.map(x=>[x.date,x.sales,x.orders,x.weather||'',x.promotion||'',x.note||''])].map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
function openEntry(day){const f=$('#entryForm');f.reset();f.date.max=today;const r=all.find(x=>x.date===day);f.date.value=r?.date||today;if(r)for(const key of ['sales','orders','weather','promotion','note'])f.elements[key].value=r[key]??'';$('#entryDialog').showModal()}
function saveRows(rows){const map=new Map(read('overrides',[]).map(r=>[r.date,r]));rows.forEach(r=>map.set(r.date,r));if(!write('overrides',[...map.values()]))return false;refresh();return true}
function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else if(quoted||!cell)quoted=!quoted;else throw Error('잘못된 따옴표입니다.')}else if(c===','&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell=''}else cell+=c}if(quoted)throw Error('닫히지 않은 따옴표가 있습니다.');row.push(cell);if(row.some(v=>v.trim()))rows.push(row);return rows}
function validateRecord(r){if(!/^\d{4}-\d{2}-\d{2}$/.test(r.date)||isNaN(date(r.date))||iso(date(r.date))!==r.date||r.date>today)throw Error('유효한 영업일을 확인하세요. 미래 날짜는 입력할 수 없습니다.');if(!Number.isSafeInteger(r.sales)||r.sales<0)throw Error('매출액은 0 이상의 안전한 정수여야 합니다.');if(r.orders!==null&&(!Number.isSafeInteger(r.orders)||r.orders<0))throw Error('거래건수는 0 이상의 안전한 정수 또는 공란이어야 합니다.');if(r.sales>0&&r.orders===0)throw Error('매출액이 있는 날의 거래건수는 1 이상 또는 공란으로 입력하세요.');for(const k of ['weather','promotion','note']){if(typeof r[k]!=='string'||r[k].length>1000)throw Error('텍스트 필드가 올바르지 않습니다.')}return r}
async function importCSV(file){try{if(!file)return;if(file.size>5e6)throw Error('CSV는 5MB 이하로 올려 주세요.');const matrix=parseCSV((await file.text()).replace(/^\uFEFF/,''));if(matrix.length<2)throw Error('헤더와 데이터 행이 필요합니다.');const header=matrix.shift().map(x=>x.trim()),idx=n=>header.indexOf(n),di=idx('날짜'),si=idx('총매출액');if(di<0||si<0)throw Error('날짜, 총매출액 헤더가 필요합니다. CSV 양식을 사용하세요.');const rows=[],seen=new Set();let skipped=0;matrix.forEach((row,i)=>{if(idx('매장')>=0&&row[idx('매장')].trim()!=='이코복스'){skipped++;return}const get=n=>(row[idx(n)]??'').trim();if(!get('총매출액'))throw Error(`${i+2}행: 매출액이 비어 있습니다.`);const number=s=>{if(!/^(\d+|\d{1,3}(,\d{3})+)$/.test(s))throw Error(`${i+2}행: 숫자 형식을 확인하세요.`);return Number(s.replaceAll(',',''))};const r=validateRecord({date:get('날짜'),sales:number(get('총매출액')),orders:get('거래건수')===''?null:number(get('거래건수')),weather:get('날씨'),promotion:get('프로모션'),note:get('특이사항')});if(seen.has(r.date))throw Error(`${i+2}행: 파일 안에 중복 날짜 ${r.date}가 있습니다.`);seen.add(r.date);rows.push(r)});if(!rows.length)throw Error('반영할 이코복스 데이터가 없습니다.');const duplicates=rows.filter(r=>all.some(x=>x.date===r.date)).length;if(!confirm(`${rows.length}일치 데이터를 반영합니다.${skipped?' 다른 매장 '+skipped+'행 제외.':''}${duplicates?' 기존 '+duplicates+'일은 교체합니다.':''}\n계속하시겠습니까?`))return;if(saveRows(rows)){toast(rows.length+'일치 매출을 반영했습니다.');render()}}catch(e){$('#importStatus').textContent='업로드 실패: '+e.message;toast('파일을 확인해 주세요. 기존 데이터는 유지됩니다.')}}
function bind(){const top=$("#topAction");top.textContent=page==="costs"?"＋ 레시피 등록":"＋ 매출 입력";top.onclick=page==="costs"?()=>costView.addRecipe():()=>openEntry();if(page==="costs"){costView.bind();return;}if(page==='weekly'){weeklyView.bind();return}if(page==="products"&&!location.hash.includes("report=legacy")){importView.bind();return}if(page==='dashboard'){salesView.bind();return}if(page==='products'){$$('[data-kind]').forEach(b=>b.onclick=()=>{productKind=b.dataset.kind;render()});$('#productMonth').onchange=e=>{productMonth=e.target.value;render()}}
if(page==='operations'){$$('[data-cadence]').forEach(b=>b.onclick=()=>{cadence=b.dataset.cadence;render()});$$('[data-check]').forEach(c=>c.onchange=()=>{const checks=read('checks',{}),set=new Set(checks[c.dataset.key]||[]);c.checked?set.add(+c.dataset.check):set.delete(+c.dataset.check);checks[c.dataset.key]=[...set];write('checks',checks);render()});$('#saveMemo').onclick=()=>{if(write('memo',$('#pmMemo').value))toast('메모를 저장했습니다.')}}
if(page==='data'){$('#dataEntry').onclick=()=>openEntry();$('#importButton').onclick=()=>$('#csvFile').click();$('#csvFile').onchange=e=>importCSV(e.target.files[0]);$('#templateButton').onclick=()=>download('이코복스_매출입력_양식.csv','\uFEFF날짜,총매출액,거래건수,날씨,프로모션,특이사항\r\n','text/csv;charset=utf-8');$('#exportAll').onclick=()=>exportCSV(all,'이코복스_전체매출.csv');$('#goalForm').onsubmit=e=>{e.preventDefault();const f=e.target,g=Number(f.goal.value);if(!Number.isSafeInteger(g)||g<=0)return toast('목표 금액을 확인해 주세요.');const goals=read('goals',{});goals[f.month.value]=g;if(write('goals',goals)){toast('월 목표를 저장했습니다.');render()}};$('#backupButton').onclick=()=>download('이코복스_업무백업_'+today+'.json',JSON.stringify({version:1,overrides:read('overrides',[]),goals:read('goals',{}),checks:read('checks',{}),memo:read('memo',''),analysis:read('analysis',null),selectedMenus:read('selectedMenus',[]),menuLaunches:read('menuLaunches',{}),forecastWeather:read('forecastWeather',{}),costs:read('costs',{version:1,ingredients:[],recipes:[]})},null,2),'application/json');$('#restoreButton').onclick=()=>$('#backupFile').click();$('#backupFile').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>5e6)throw Error('파일은 5MB 이하로 올려 주세요.');const b=JSON.parse(await file.text());if(b.version!==1||!Array.isArray(b.overrides)||!b.goals||typeof b.goals!=='object'||Array.isArray(b.goals)||!b.checks||typeof b.checks!=='object'||Array.isArray(b.checks)||typeof b.memo!=='string')throw Error('올바른 백업이 아닙니다.');b.overrides.forEach(validateRecord);if(new Set(b.overrides.map(x=>x.date)).size!==b.overrides.length)throw Error('중복 날짜가 있습니다.');for(const [m,g]of Object.entries(b.goals))if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(m)||!Number.isSafeInteger(g)||g<=0)throw Error('목표 형식이 잘못되었습니다.');for(const [k,v]of Object.entries(b.checks))if(!/^(daily|weekly|monthly):\d{4}-\d{2}(-\d{2})?$/.test(k)||!Array.isArray(v)||v.some(n=>!Number.isInteger(n)||n<0||n>4)||new Set(v).size!==v.length)throw Error('체크리스트 형식이 잘못되었습니다.');if(!confirm('현재 브라우저의 수정 매출·목표·업무 기록을 백업 내용으로 교체할까요?'))return;if(b.analysis){if(!Array.isArray(b.analysis.products)||!Array.isArray(b.analysis.productCoverage)||!Array.isArray(b.analysis.hourly)||!Array.isArray(b.analysis.hourlyCoverage))throw Error('분석 자료 형식이 잘못되었습니다.');for(const row of b.analysis.products){if(typeof row.category!=='string'||typeof row.name!=='string'||row.category.length>200||row.name.length>500||!Number.isSafeInteger(row.sales)||!Number.isSafeInteger(row.qty))throw Error('상품 자료 형식이 잘못되었습니다.');validateRecord({date:row.date,sales:0,orders:null,weather:'',promotion:'',note:''})}for(const row of b.analysis.hourly){if(!Number.isInteger(row.hour)||row.hour<0||row.hour>23||!Number.isSafeInteger(row.sales)||!Number.isSafeInteger(row.orders))throw Error('시간대 자료 형식이 잘못되었습니다.');validateRecord({date:row.date,sales:0,orders:null,weather:'',promotion:'',note:''})}for(const dt of [...b.analysis.productCoverage,...b.analysis.hourlyCoverage])validateRecord({date:dt,sales:0,orders:null,weather:'',promotion:'',note:''})}if(b.selectedMenus&&(!Array.isArray(b.selectedMenus)||b.selectedMenus.length>12||b.selectedMenus.some(v=>typeof v!=='string')))throw Error('메뉴 선택 자료가 잘못되었습니다.');if(b.menuLaunches&&(typeof b.menuLaunches!=='object'||Array.isArray(b.menuLaunches)))throw Error('출시일 자료가 잘못되었습니다.');if(b.forecastWeather){if(typeof b.forecastWeather!=='object'||Array.isArray(b.forecastWeather)||Object.keys(b.forecastWeather).length>365)throw Error('예상 날씨 형식이 잘못되었습니다.');for(const [dt,v]of Object.entries(b.forecastWeather))if(!/^\d{4}-\d{2}-\d{2}$/.test(dt)||isNaN(date(dt))||iso(date(dt))!==dt||!['normal','rain','heat','snow'].includes(v))throw Error('예상 날씨 형식이 잘못되었습니다.')}if(b.costs!==undefined)validateCosts(b.costs);for(const k of ['overrides','goals','checks','memo','analysis','selectedMenus','menuLaunches','forecastWeather','costs'])if(b[k]!==undefined&&!write(k,b[k]))throw Error('저장에 실패했습니다.');refresh();toast('백업을 복원했습니다.');render()}catch(e){toast('복원 실패: '+e.message)}};$('#resetButton').onclick=()=>{if(!confirm('현재 브라우저의 추가·수정 매출, 업로드한 상품·시간대, 메뉴 설정, 재료 단가·레시피, 목표, 체크리스트와 메모를 삭제하고 초기 스냅샷으로 되돌릴까요? 먼저 백업을 권장합니다.'))return;try{['overrides','goals','checks','memo','analysis','selectedMenus','menuLaunches','forecastWeather','costs'].forEach(k=>localStorage.removeItem('ikovox:'+k));refresh();toast('초기 스냅샷으로 되돌렸습니다.');render()}catch{toast('브라우저 저장 설정을 확인하세요.')}}}}
const costView=createCostView({$,$$,esc,read,write,toast,rerender:render,download,today});
const importView=createImportView({$,$$,esc,nf,won,sum,getAnalysis:()=>analysisBase,getChannels:()=>channelBase,catalog:()=>catalog,download,csvCell,rerender:render,toast});
const salesView=createSalesView({$,$$,esc,nf,won,iso,date,add,sum,read,write,toast,getRows:()=>all,getWeather:()=>weatherBase,getAnalysis:()=>analysisBase,getChannels:()=>channelBase,catalog:()=>catalog,saveRows,openEntry,today,lineChart,parseCSV,download,csvCell,rerender:render,source:'https://docs.google.com/spreadsheets/d/199eVxgoHIhX_wllhiukXI9HgeBjmlzS9v-dFKYF7i4s/edit'});
const weeklyView=createWeeklyView({$,$$,esc,nf,won,read,today,getRows:()=>all,getAnalysis:()=>analysisBase,getChannels:()=>channelBase,getSalesData:()=>salesView.data(),catalog:()=>catalog,rerender:render,download,csvCell,importHourly:file=>salesView.importAnalysis(file,'hourly')});
$('#topAction').onclick=()=>openEntry();$('#menuToggle').onclick=()=>document.body.classList.toggle('menu-open');$('#closeDialog').onclick=()=>$('#entryDialog').close();$('#entryForm').onsubmit=e=>{e.preventDefault();const f=e.target;try{const r=validateRecord({date:f.date.value,sales:Number(f.sales.value),orders:f.orders.value===''?null:Number(f.orders.value),weather:f.weather.value,promotion:f.promotion.value,note:f.note.value});if(all.some(x=>x.date===r.date)&&!confirm(r.date+'의 기존 매출을 교체할까요?'))return;if(saveRows([r])){$('#entryDialog').close();toast('매출을 저장했습니다.');render()}}catch(e){toast(e.message)}};
window.addEventListener('hashchange',render);$('.today').textContent=today.replace(/(\d+)-(\d+)-(\d+)/,(_,y,m,d)=>`${y}년 ${+m}월 ${+d}일`);
try{const response=await fetch('data.json');if(!response.ok)throw Error('데이터 파일을 불러올 수 없습니다.');base=await response.json();const detailResponse=await fetch('analysis-data.json');if(!detailResponse.ok)throw Error('상품 데이터 파일을 불러올 수 없습니다.');analysisBase=await detailResponse.json();const channelsResponse=await fetch('channel-data.json');if(!channelsResponse.ok)throw Error('채널 검토 자료를 불러올 수 없습니다.');channelBase=await channelsResponse.json();const directResponse=await fetch('direct-delivery.json');if(!directResponse.ok)throw Error('배달 직접 원본을 불러올 수 없습니다.');channelBase.direct=await directResponse.json();const weatherResponse=await fetch('weather-data.json',{cache:'no-store'});if(!weatherResponse.ok)throw Error('날씨 자료를 불러올 수 없습니다.');weatherBase=await weatherResponse.json();const catalogResponse=await fetch('product-master.json');if(!catalogResponse.ok)throw Error('상품 통합 기준을 불러올 수 없습니다.');catalog=createProductCatalog(await catalogResponse.json());refresh();end=all.at(-1).date;start=end.slice(0,7)+'-01';render()}catch(e){$('#content').innerHTML='<section class="card empty">데이터를 불러오지 못했습니다. 페이지를 새로고침해 주세요.</section>';console.error(e)}
